function switchDocument(id){finishEditing();current=id;project.activeDocument=id;clear();drawing=null;drag=null;tool='select';view={mode:'plan',side:'front',azimuth:35,elevation:35};closeMenus();render();fit();persist()}
function createDocument(type,name){if(project.documents.length>=30)return;const before=snapshot(),d=M.createDocument(type,name);project.documents.push(d);history(before);switchDocument(d.id)}
function closeMenus(){$('#context-menu').hidden=true;$('#export-popover').hidden=true}
