 if(action==='select-all'){selection=doc().objects.filter(o=>o.visible&&(!doc().floors||o.floor===doc().activeFloor)).map(o=>o.id);primary=selection.find(id=>doc().objects.find(o=>o.id===id)?.type!=='hole')||selection[0];floorSelection=null;render();return}
